fun <S> explore(initial: S, next: (S) -> List<Pair<String, S>>, invariant: (S) -> Boolean): List<String>? {
    val parent = HashMap<S, Pair<S, String>?>()      // how each state was first reached; also "seen"
    val queue = ArrayDeque(listOf(initial))
    parent[initial] = null
    while (queue.isNotEmpty()) {
        val s = queue.removeFirst()
        if (!invariant(s)) {                            // walk the parents back to the start
            val trace = ArrayDeque<String>()
            var at = s
            while (true) {
                val (from, step) = parent.getValue(at) ?: break
                trace.addFirst(step)
                at = from
            }
            return trace.toList()
        }
        for ((step, t) in next(s)) {
            if (t !in parent) {
                parent[t] = s to step
                queue.addLast(t)
            }
        }
    }
    return null
}

// Shortest: a FIFO queue hands out every state 1 step away before any state 2 steps away.
// Ends on loops: a state already in `parent` is never queued again, and the model has finitely many states.
